'use strict';
let page='home',query='',type='All',temp='All temperatures',transportView='table',lastFocus;
const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Device storage is full. Changes remain active in this session.');}};
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>t.classList.remove('show'),3500);}
function notify(text){state.notifications.unshift(text);state.notifications=state.notifications.slice(0,20);save();}
const btn=(text,action,cls='',id='')=>'<button class="btn '+cls+'" data-action="'+action+'" data-id="'+esc(id)+'">'+text+'</button>';
const badge=(text,cls='')=>'<span class="badge '+cls+'">'+esc(text)+'</span>';
const detail=(name,val)=>'<div><span>'+esc(name)+'</span><strong>'+esc(val)+'</strong></div>';
function status(s){return s.status==='Delivered'?badge('Delivered','teal'):s.status==='Canceled'?badge('Canceled','red'):s.review?badge('Review needed','amber'):s.status==='In transit'?badge('In transit','blue'):confirmed(s)>=target(s)&&target(s)>0?badge('Funded · planning','teal'):badge('Funding open','amber');}
function bar(s){const t=target(s)||1;return '<div class="progress"><span style="width:'+Math.min(100,confirmed(s)/t*100)+'%"></span><span class="pending" style="width:'+Math.max(0,Math.min(100-confirmed(s)/t*100,pending(s)/t*100))+'%"></span></div><div class="progress-label"><span>'+money(confirmed(s))+' confirmed · '+money(pending(s))+' pending</span><span>'+money(target(s))+' target</span></div>';}
function head(eye,title,sub,action=''){return '<div class="page-head"><div><div class="eyebrow">'+eye+'</div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="row wrap">'+action+'</div></div>';}
function foodCard(f){return '<article class="food-card" role="button" tabindex="0" data-action="food" data-id="'+f.id+'" aria-label="Open '+esc(f.title)+'"><div class="food-band '+f.band+'">'+icon(f.icon)+badge(openFood(f)?f.type:'Closed',f.type==='Donation'?'teal':f.type==='Food needed'?'amber':'')+'</div><div class="food-body"><h3>'+esc(f.title)+'</h3><div class="org">'+esc(f.org)+'</div><div class="food-data"><span><strong>'+f.pallets+' pallets</strong> · '+num(f.pounds)+' lb</span>'+badge(f.temp,'gray')+'</div><div class="food-meta">'+icon('pin')+esc(f.city)+'</div><div class="food-meta">'+icon('clock')+'By '+date(f.deadline)+'<span style="margin-left:auto">'+(f.type==='Donation'?Math.max(0,f.pallets-held(f))+' pallets available':f.price?money(f.price)+'/pallet':'View opportunity')+'</span></div></div></article>';}
function go(p){page=p;query='';type='All';temp='All temperatures';closeDialog();render();window.scrollTo(0,0);}
function render(){const titles={home:'Network overview',food:'Food & needs',transport:'Transportation',sponsor:'Sponsor a delivery',impact:'Impact'};document.getElementById('app').innerHTML='<aside class="sidebar"><div class="brand"><div class="wordmark">BHD</div><div class="brand-sub">FOOD BANK<br>NETWORK</div></div><div class="eyebrow">MOVE GOOD FORWARD</div><nav class="nav" aria-label="Main navigation">'+[['home','home','Overview'],['food','food','Food & needs'],['transport','truck','Transportation'],['sponsor','heart','Sponsor a delivery'],['impact','chart','Impact']].map(([p,i,t])=>'<button data-page="'+p+'" class="'+(page===p?'active':'')+'" title="'+t+'" '+(page===p?'aria-current="page"':'')+'>'+icon(i)+'<span>'+t+'</span></button>').join('')+'</nav><div class="side-bottom"><div class="eyebrow">BUILT AROUND COMMUNITY</div><p>Find the food.<br>Share the journey.<br>Fund the delivery.</p><button data-action="tour" title="Guided demo">'+icon('info')+'<span>Explore the demo</span></button><button data-action="reset" title="Reset demo">'+icon('reset')+'<span>Reset demo</span></button></div></aside><main class="main"><header class="topbar"><div class="crumb">Food Bank Network '+icon('chevron')+'<strong>'+titles[page]+'</strong></div><div class="top-tools"><span class="demo">DEMO NETWORK</span><select id="role" aria-label="Demo portal role">'+[['bank','Food Banks'],['donor','Donors & Sponsors'],['ops','BHD Operations']].map(([v,l])=>'<option value="'+v+'" '+(v===state.role?'selected':'')+'>'+l+'</option>').join('')+'</select><button class="bell" data-action="activity" aria-label="Activity notifications">'+icon('bell')+'</button><div class="avatar">'+(ops()?'BHD':state.role==='bank'?'FB':'DS')+'</div></div></header><div class="content">'+({home:homePage,food:foodPage,transport:transportPage,sponsor:sponsorPage,impact:impactPage}[page])()+'<footer class="footer"><span>Powered by Backhaul Direct · Moving food. Connecting communities.</span><span>Illustrative data · Local demo changes · No live payments</span></footer></div></main>';}
function homePage(){const s=ship('D-2084'),ds=state.shipments.filter(s=>s.status==='Delivered');return head('MONDAY, OCTOBER 26 · REGIONAL PILOT','More food. Fewer barriers.','A shared place to find food, coordinate transportation, and fund the journey.',btn(icon('plus')+' Post an opportunity','post','dark'))+'<div class="actions">'+[['food','food','Find food','See what’s available'],['plus','offer','Offer food','Put surplus to work'],['truck','transport','Arrange transportation','Connect the journey'],['heart','sponsor','Sponsor a delivery','Help food get there']].map(([i,p,l,sub])=>'<button class="action '+(p==='sponsor'?'highlight':'')+'" data-action="quick" data-id="'+p+'"><span class="tile">'+icon(i)+'</span><span><strong>'+l+'</strong><small>'+sub+'</small></span></button>').join('')+'</div><div class="home-grid"><section class="feature"><div class="feature-body"><div class="section-head"><div class="eyebrow">FEATURED DELIVERY · '+s.id+'</div>'+status(s)+'</div><h2>Good food is ready.<br>Help it get there.</h2><p>'+num(s.pounds)+' pounds of produce. Three food banks. One shared journey.</p><div class="route">'+s.route.map((r,i)=>'<div class="stop"><strong>'+r+'</strong>'+(i?'Food bank':'Food pickup')+'</div>').join('')+'</div>'+bar(s)+'</div><div class="feature-bottom"><div><strong>'+money(available(s))+'</strong> <span class="small">open to sponsor</span><small>'+money(Math.max(0,target(s)-confirmed(s)))+' awaiting confirmed funding</small></div>'+btn('Fund the delivery '+icon('arrow'),'pledge','primary',s.id)+'</div></section><section class="card pad"><div class="section-head"><h2>A little coordination.<br>A greater reach.</h2>'+icon('leaf')+'</div><div class="stats">'+[['box',num(ds.reduce((a,s)=>a+s.receipt.pounds,0)),'pounds delivered<br>in the demo network'],['truck',ds.length,'deliveries<br>completed'],['heart',money(ds.reduce((a,s)=>a+confirmed(s),0)),'transportation funding<br>applied to deliveries']].map(([i,v,l])=>'<div class="stat">'+icon(i)+'<strong>'+v+'</strong><span>'+l+'</span></div>').join('')+'</div><div class="note">Impact counts completed deliveries. Pending pledges stay separate.</div></section></div><div class="section-head"><div><h2>Good food looking for its next stop</h2><p>Explore available donations across the network.</p></div>'+btn('View the board '+icon('arrow'),'quick','ghost','food')+'</div><div class="food-grid">'+state.items.filter(f=>openFood(f)&&f.type==='Donation').slice(0,3).map(foodCard).join('')+'</div><div class="strip"><div class="row">'+icon('users')+'<span><strong>Better together.</strong> Food banks, donors, fleets, and sponsors sharing one coordinated network.</span></div>'+btn('Take the five-minute tour '+icon('arrow'),'tour','ghost')+'</div>';}
function foodPage(){const fs=state.items.filter(f=>(type==='All'||type===f.type)&&(temp==='All temperatures'||temp===f.temp)&&(f.title+' '+f.product+' '+f.city+' '+f.org).toLowerCase().includes(query.toLowerCase()));return head('FOOD & COMMUNITY','Find the food. Share the opportunity.','Available food, local needs, shared orders, and room on the return trip.',btn(icon('plus')+' Post an opportunity','post','dark'))+(state.role==='bank'?'<div class="portal"><div class="row">'+icon('users')+' Requesting for <select id="bank" aria-label="Food bank organization">'+(state.exchange?state.exchange.partners.filter(p=>p.kind==='Food bank').map(p=>p.name):banks).map(b=>'<option '+(b===state.bank?'selected':'')+'>'+b+'</option>').join('')+'</select></div>'+btn('Receiving preferences','profile','ghost')+'</div>':'')+'<div class="filters"><div class="search">'+icon('search')+'<input id="search" class="input" aria-label="Search food board" placeholder="Search food, location, or organization" value="'+esc(query)+'"></div><select id="temperature" class="input" aria-label="Temperature filter">'+['All temperatures','Ambient','Refrigerated','Frozen'].map(t=>'<option '+(t===temp?'selected':'')+'>'+t+'</option>').join('')+'</select>'+btn(icon('bell')+' Save search','save-search')+'</div><div class="filters tabs">'+['All','Donation','Food needed','Shared order','For sale','Capacity'].map(t=>'<button class="tab '+(type===t?'active':'')+'" data-action="filter" data-id="'+t+'">'+(t==='All'?'All opportunities':t==='Donation'?'Donations':t)+'</button>').join('')+'</div><div class="food-grid">'+(fs.map(foodCard).join('')||'<div class="empty">No matching opportunities. Try another filter.</div>')+'</div>';}
function transportPage(){return head('SHARED TRANSPORTATION','Every delivery, accounted for.','Coordinate shared routes, owned fleets, funding, and delivery confirmation.',btn(icon('download')+' Export shipments','export'))+(ops()?'<section class="card pad" style="margin-bottom:21px;border-left:3px solid var(--teal)"><div class="section-head"><h2>BHD operations queue</h2>'+badge('Active deliveries','blue')+'</div><div class="tabs">'+state.shipments.filter(s=>!['Delivered','Canceled'].includes(s.status)).map(s=>btn(s.id+' · '+(s.review?'Review required':accepted(item(s.itemId))<s.pallets?'Recipient acceptance':confirmed(s)<target(s)?'Confirm funding':!s.carrier?'Assign capacity':'Review dispatch'),'ship','sm',s.id)).join('')+'</div></section>':'<div class="note blue" style="margin:0 0 21px">Switch to BHD Operations to quote, assign capacity, and release a delivery.</div>')+'<div class="section-head"><div class="tabs">'+['table','calendar'].map(v=>'<button class="tab '+(transportView===v?'active':'')+'" data-action="transport-view" data-id="'+v+'">'+(v==='table'?'Shipment list':'Shared calendar')+'</button>').join('')+'</div><span class="small muted">'+state.shipments.length+' demo shipments</span></div>'+(transportView==='table'?'<div class="card table-wrap"><table><thead><tr><th>DELIVERY</th><th>ROUTE</th><th>PICKUP</th><th>LOAD</th><th>FUNDING</th><th>STATUS</th><th></th></tr></thead><tbody>'+state.shipments.map(s=>'<tr class="clickable" tabindex="0" data-action="ship" data-id="'+s.id+'"><td><div class="table-id">'+s.id+'</div><strong>'+esc(s.title)+'</strong><small>'+s.temp+'</small></td><td>'+esc(s.origin)+'<small>'+esc(s.dest)+'</small></td><td>'+date(s.date)+'</td><td>'+s.pallets+' pallets<small>'+num(s.pounds)+' lb</small></td><td>'+money(confirmed(s))+' / '+money(target(s))+'<small>'+money(pending(s))+' pending</small></td><td>'+status(s)+'</td><td>'+icon('chevron')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="calendar">'+[26,27,28,29,30].map(d=>'<div class="day">'+['MON','TUE','WED','THU','FRI'][d-26]+'<strong>'+d+' October</strong>'+state.shipments.filter(s=>s.date==='2026-10-'+d).map(s=>'<button class="calendar-load" data-action="ship" data-id="'+s.id+'"><strong>'+s.id+' · '+esc(s.title)+'</strong>'+esc(s.origin)+'<br>'+s.pallets+' pallets · '+s.temp+'</button>').join('')+'</div>').join('')+'</div>')+'<div class="two-col"><section class="card pad"><div class="section-head"><h2>Room on the return trip</h2>'+icon('truck')+'</div><p class="small muted">Valley Community Fleet · Columbus → Indianapolis<br>8 pallet spaces · 12,000 lb · Refrigerated<br>Friday, October 30 · 10 am–4 pm</p><div style="margin-top:16px">'+btn('View available capacity '+icon('arrow'),'food','ghost','F-1047')+'</div></section><section class="card pad"><div class="section-head"><h2>A suggested shared route</h2>'+icon('users')+'</div><p class="small muted">Three produce allocations could travel together from Indianapolis through Ohio. Weight, temperature, shelf life, and appointments require operations review.</p><div style="margin-top:16px">'+btn('Review the produce delivery '+icon('arrow'),'ship','ghost','D-2084')+'</div></section></div>';}
function sponsorPage(){return head('TURN GENEROSITY INTO DELIVERY','The food is donated. Fund the journey.','Choose a delivery. Cover all or part of the transportation. See it arrive.')+'<div class="sponsor-grid">'+(state.shipments.filter(s=>s.status==='Planning'&&!s.review).map(s=>'<article class="sponsor-card"><div class="sponsor-banner">'+icon(s.temp==='Ambient'?'box':s.itemId==='F-1044'?'dairy':'food')+badge(s.date==='2026-10-27'?'Pickup tomorrow':num(s.pounds)+' lb of food',s.date==='2026-10-27'?'amber':'teal')+'</div><div class="pad"><div class="eyebrow muted">'+s.id+' · '+s.temp+'</div><h3>'+esc(s.title)+'</h3><p>'+esc(s.origin)+' → '+esc(s.dest)+'<br>Pickup '+date(s.date)+'</p><div class="funding"><strong>'+money(available(s))+'</strong> <small class="muted">open to sponsor</small>'+bar(s)+'</div></div><div class="sponsor-foot">'+btn('Sponsor this delivery '+icon('arrow'),'pledge','dark full',s.id)+'</div></article>').join('')||'<div class="empty">No deliveries currently open to sponsorship.</div>')+'</div><div class="two-col"><section class="card pad extra">'+icon('calendar')+'<div><div class="eyebrow muted">MAKE IT A REGULAR THING</div><h3>Adopt a weekly delivery</h3><p>Support a recurring route with a monthly cap. Start with your interest, then agree the schedule and cost.</p>'+btn('Explore route sponsorship '+icon('arrow'),'recurring','ghost')+(state.recurring.length?'<p style="margin-top:10px">'+state.recurring.length+' demo interests recorded</p>':'')+'</div></section><section class="card pad extra">'+icon('heart')+'<div><div class="eyebrow muted">GO FURTHER, TOGETHER</div><h3>A little help. Matched.</h3><p>Cedar Works offers a demo dollar-for-dollar match up to $500 toward the pantry-staples delivery. Both pledges require confirmation.</p>'+btn('Join the matching campaign '+icon('arrow'),'match','ghost',state.match.shipment)+'</div></section></div><div class="note">Demonstration only. Sponsorship records a simulated pledge for transportation services. No payment is collected. Quotes include transportation, handling, and BHD coordination.</div>';}
function deliveredImpactPage(){const ds=state.shipments.filter(s=>s.status==='Delivered'),lbs=ds.reduce((a,s)=>a+s.receipt.pounds,0),funds=ds.reduce((a,s)=>a+confirmed(s),0),served=new Set(ds.flatMap(s=>s.itemId?item(s.itemId).allocations.filter(a=>a.status==='Confirmed').map(a=>a.bank):[s.receipt.bank])).size,sponsors={};ds.forEach(s=>deliveryPledges(s).filter(p=>p.status==='Confirmed'&&!p.sourceBuyer).forEach(p=>{sponsors[p.sponsor]??={funds:0,lbs:0};sponsors[p.sponsor].funds+=p.amount;sponsors[p.sponsor].lbs+=s.receipt.pounds*p.amount/target(s);}));return head('DELIVERY IS THE DIFFERENCE','Good intentions. Confirmed impact.','Completed deliveries, demonstration receipts, and transparent transportation funding.',btn(icon('download')+' Export impact','export-impact'))+'<div class="metrics">'+[['Pounds delivered',num(lbs)],['Deliveries completed',ds.length],['Food banks served',served],['Funding applied',money(funds)]].map(([l,v])=>'<button class="metric" data-action="impact-records"><span>'+l+'</span><strong>'+v+'</strong></button>').join('')+'</div><div class="card"><div class="pad section-head" style="margin:0"><h2>Every delivery has a record</h2>'+badge('Completed only','teal')+'</div><div class="table-wrap" id="impact-records"><table><thead><tr><th>DELIVERY</th><th>DESTINATION</th><th>RECEIVED</th><th>POUNDS</th><th>FUNDING APPLIED</th><th>EVIDENCE</th></tr></thead><tbody>'+ds.map(s=>'<tr><td><strong>'+esc(s.title)+'</strong><small>'+s.id+'</small></td><td>'+esc(s.dest)+'</td><td>'+date(s.receipt.date)+'</td><td>'+num(s.receipt.pounds)+'</td><td>'+money(confirmed(s))+'</td><td>'+btn('View receipt','receipt','ghost',s.id)+'</td></tr>').join('')+'</tbody></table></div></div><div class="two-col"><section class="card pad"><div class="section-head"><h2>Sponsors moving food forward</h2>'+icon('heart')+'</div>'+Object.entries(sponsors).map(([n,x])=>'<div class="allocation"><div><strong>'+esc(n)+'</strong><small>'+num(Math.round(x.lbs))+' lb attributed proportionally</small></div><strong>'+money(x.funds)+'</strong></div>').join('')+'<p class="small muted" style="margin-top:14px">Pounds are attributed by each sponsor’s share of delivery funding. Rounding may cause small differences.</p></section><section class="card pad"><div class="section-head"><h2>Still on the way</h2>'+icon('truck')+'</div><h2>'+num(state.shipments.filter(s=>!['Delivered','Canceled'].includes(s.status)).reduce((a,s)=>a+s.pounds,0))+' lb planned</h2><p class="small muted" style="margin:12px 0 18px">Planned food and pending pledges are excluded from completed impact.</p>'+btn('See active deliveries '+icon('arrow'),'quick','ghost','transport')+'<div class="note">All organizations and receipts are fictional demonstration records.</div></section></div>';}
function dialog(title,body,eye='',modal=false){if(!document.getElementById('overlay').firstChild)lastFocus=document.activeElement;document.body.classList.add('no-scroll');document.getElementById('overlay').innerHTML='<div class="overlay '+(modal?'modal-wrap':'')+'" data-backdrop><section class="'+(modal?'modal':'drawer')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><header class="dialog-head"><div><div class="eyebrow muted">'+eye+'</div><h2>'+title+'</h2></div><button class="close" data-action="close" aria-label="Close dialog">'+icon('close')+'</button></header><div class="dialog-body">'+body+'</div></section></div>';setTimeout(()=>document.querySelector('.close')?.focus(),0);}
function closeDialog(){document.getElementById('overlay').innerHTML='';document.body.classList.remove('no-scroll');lastFocus?.focus?.();}
function field(name,label,kind='text',value='',attrs=''){return '<div class="field"><label for="f-'+name+'">'+label+'</label><input class="input" id="f-'+name+'" name="'+name+'" type="'+kind+'" value="'+esc(value)+'" '+attrs+'></div>';}
function select(name,label,options,value=''){return '<div class="field"><label for="f-'+name+'">'+label+'</label><select class="input" id="f-'+name+'" name="'+name+'">'+options.map(o=>'<option '+(o===value?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select></div>';}
const area=(name,label,value='')=>'<div class="field wide"><label for="f-'+name+'">'+label+'</label><textarea class="input" name="'+name+'" id="f-'+name+'">'+esc(value)+'</textarea></div>';
const form=(kind,body,id='',label='Save',cls='dark')=>'<form data-form="'+kind+'" data-id="'+id+'"><div class="error" role="alert"></div>'+body+'<button type="submit" class="btn '+cls+' full">'+label+'</button></form>';
function foodDetail(fid){const f=item(fid),s=state.shipments.find(s=>s.itemId===fid),left=Math.max(0,f.pallets-held(f));dialog(f.title,badge(f.type,f.type==='Donation'?'teal':'blue')+' '+badge(openFood(f)?'Open':'Closed')+(f.photo?'<img src="'+f.photo+'" alt="Food offer photo" style="width:100%;max-height:210px;object-fit:cover;border-radius:8px;margin-top:15px">':'')+'<p class="muted" style="margin-top:14px">'+esc(f.org)+' · '+esc(f.city)+'</p><p>'+esc(f.notes)+'</p><div class="details">'+detail('Quantity',f.pallets+' pallets · '+num(f.pounds)+' lb')+detail('Temperature',f.temp)+detail('Pickup / response deadline',date(f.deadline))+detail('Shelf life / availability',f.shelf)+detail('Available to request',left+' pallets')+detail('Product cost',f.type==='Donation'?'Donated food':f.price?money(f.price)+'/pallet':'Confirm with owner')+'</div>'+(f.type==='Donation'?'<div class="note">Food is donated. Transportation and handling may still need funding. A request holds quantity until the donor confirms or declines.</div>':'')+(['Donation','For sale','Shared order'].includes(f.type)?'<h3>Food allocations</h3>'+(f.allocations.map(a=>'<div class="allocation"><div><strong>'+esc(a.bank)+'</strong><small>'+a.pallets+' pallets · '+num(Math.round(f.pounds*a.pallets/f.pallets))+' lb</small></div><div>'+badge(a.status,a.status==='Confirmed'?'teal':a.status==='Requested'?'amber':'gray')+(a.status==='Requested'&&['donor','ops'].includes(state.role)?'<div class="row" style="margin-top:6px">'+btn('Approve','approve','sm',f.id+'|'+a.id)+btn('Decline','decline','sm',f.id+'|'+a.id)+'</div>':'')+'</div></div>').join('')||'<p class="small muted">No allocations yet. Request the first quantity.</p>')+(state.role==='bank'&&openFood(f)&&left>0?'<h3>Request food</h3>'+form('request','<p class="small muted" style="margin-bottom:12px">Requesting for '+esc(state.bank)+'</p>'+field('pallets','Pallets requested','number',1,'required min="1" max="'+left+'" step="1"')+'<label class="check"><input type="checkbox" required> I can receive this product within the temperature, shelf-life, and delivery requirements.</label>',f.id,'Request allocation','primary'):state.role==='bank'&&left===0?'<div class="note">All pallets are held or confirmed.</div>':''):'')+(openFood(f)&&['For sale','Shared order'].includes(f.type)&&f.price>0?'<hr class="rule"><div class="note">This food has a purchase cost. Supporters can fund the food, transportation, or both. Funding does not reserve stock or place an order.</div>'+btn('Fund the order '+icon('arrow'),'order-from-food','primary full',f.id):'')+(s?'<hr class="rule">'+btn('View linked delivery '+icon('arrow'),'ship','full',s.id):ops()&&['Donation','For sale','Shared order'].includes(f.type)?btn('Create transportation request','create-shipment','dark full',f.id):'')+'<h3>Conversation</h3>'+(f.comments.map(c=>'<div class="comment"><strong>'+esc(c.name)+'</strong>'+esc(c.text)+'</div>').join('')||'<p class="small muted">Ask a question or respond to this opportunity.</p>')+form('comment',area('message','Your message'),fid,'Post message')+(['donor','ops'].includes(state.role)&&f.status==='Open'?'<hr class="rule">'+btn('Close / mark unavailable','close-offer','danger full',f.id):''),f.id+' · COMMUNITY BOARD');}
function postDialog(){dialog('Put an opportunity on the board',form('post','<div class="form-grid">'+select('type','Opportunity type',['Donation','Food needed','Shared order','For sale','Capacity'])+field('org','Organization','text',state.role==='bank'?state.bank:'','required maxlength="80"')+field('title','Post title','text','','required maxlength="80"')+field('product','Product or capacity','text','','required maxlength="80"')+field('city','Pickup location or route','text','','required maxlength="100"')+select('temp','Temperature',['Ambient','Refrigerated','Frozen'])+field('pallets','Pallets / spaces','number','','required min="1" max="1000" step="1"')+field('pounds','Total weight / capacity (lb)','number','','required min="1" max="1000000" step="1"')+field('deadline','Pickup / response deadline','date','2026-10-30','required min="'+demoDate+'"')+field('shelf','Shelf life / availability','text','','required maxlength="120"')+field('price','Product price / pallet (sales only)','number',0,'min="0" step="0.01"')+field('photo','Optional food photo','file','','accept="image/png,image/jpeg,image/webp"')+area('notes','Pickup, product, and receiving details')+'</div><p class="small muted" style="margin-bottom:16px">Demo only. Photos remain local, maximum 1 MB. Donations have zero product price; transportation is separate.</p>','','Publish demo opportunity','primary'),'NEW OPPORTUNITY',true);}
function quote(s){return '<div class="quote-line"><span>Transportation</span><span>'+money(s.linehaul)+'</span></div><div class="quote-line"><span>Handling / stops</span><span>'+money(s.handling)+'</span></div><div class="quote-line"><span>BHD coordination</span><span>'+money(s.fee)+'</span></div><div class="quote-line total"><span>Total transportation target</span><span>'+money(target(s))+'</span></div>';}
function pledgeDialog(sid,match=false){const s=ship(sid);if(s.status!=='Planning'||s.review||available(s)<=0||target(s)<=0){shipDetail(sid);toast('This delivery is fully pledged or awaiting review.');return;}const used=activePledges(s).filter(p=>p.kind==='Match').reduce((a,p)=>a+p.amount,0);dialog('Fund this delivery','<div class="eyebrow" style="color:var(--teal)">'+s.id+' · '+num(s.pounds)+' LB OF FOOD</div><h3 style="font-size:21px">'+esc(s.title)+'</h3><p class="muted small">'+esc(s.origin)+' → '+esc(s.dest)+'</p><div class="details">'+detail('Pickup deadline',date(s.date))+detail('Open to new pledges',money(available(s)))+'</div>'+quote(s)+bar(s)+(match?'<div class="note">Cedar Works adds a pending match, up to '+money(Math.max(0,500-used))+' remaining and the delivery’s funding gap. Both pledges require confirmation.</div>':'')+'<h3>Your sponsorship</h3><div class="row wrap" style="margin-bottom:15px">'+[100,250,500].filter(n=>n<=available(s)).map(n=>btn(money(n),'amount','',n)).join('')+(!match?btn('Remaining '+money(available(s)),'amount','',available(s)):'')+'</div>'+form('pledge','<input type="hidden" name="match" value="'+(match?'yes':'no')+'">'+field('sponsor','Sponsor / company','text','','required maxlength="80"')+field('amount','Pledge amount ($)','number',Math.min(250,match?available(s)/2:available(s)),'required min="0.01" step="0.01" max="'+available(s)+'"')+'<div class="note blue" style="margin-bottom:15px">Intended service provider: Backhaul Direct. This records a transportation pledge only. No payment is collected and no tax receipt is issued.</div><label class="check"><input type="checkbox" required> I understand this is a simulated pledge, pending confirmation.</label>',s.id,'Record demo pledge','primary')+'<hr class="rule">'+btn('View delivery and allocations','ship','ghost',s.id),'SPONSOR A DELIVERY');}
function shipDetail(sid){const s=ship(sid),f=item(s.itemId),active=!['Canceled','Delivered'].includes(s.status),acceptedAll=!f||accepted(f)===s.pallets;dialog(s.title,status(s)+'<div class="details">'+detail('Origin',s.origin)+detail('Delivery route',s.dest)+detail('Pickup',date(s.date))+detail('Load',s.pallets+' pallets · '+num(s.pounds)+' lb')+detail('Temperature',s.temp)+detail('Assigned capacity',s.carrier||'Not assigned')+'</div>'+(f?btn('View food and allocations '+icon('arrow'),'food','ghost',f.id)+'<div class="note '+(acceptedAll?'':'amber')+'">'+accepted(f)+' of '+s.pallets+' pallets accepted by recipients. '+(acceptedAll?'Allocations confirmed.':'Outstanding requests need approval.')+'</div><h3>Estimated transportation allocation</h3>'+f.allocations.filter(a=>a.status!=='Declined').map(a=>'<div class="quote-line"><span>'+esc(a.bank)+' · '+a.pallets+' pallets</span><span>'+money(target(s)*a.pallets/s.pallets)+'</span></div>').join('')+'<p class="small muted">Illustrative allocation by pallet share. Participants must agree costs; sponsorship reduces the amount recipients need to fund.</p>':'')+(s.review?'<div class="note red">Review required: '+esc(s.review)+' Funding remains assigned to this delivery until reconciled.</div>':'')+'<h3>Transportation quote</h3>'+quote(s)+'<p class="small muted" style="margin-top:9px">Illustrative quote. Food value is excluded.</p>'+bar(s)+'<h3>Funding ledger</h3>'+(s.pledges.map(p=>'<div class="allocation"><div><strong>'+esc(p.sponsor)+'</strong><small>'+p.kind+' sponsorship · '+money(p.amount)+'</small></div><div>'+badge(p.status,p.status==='Confirmed'?'teal':p.status==='Pending'?'amber':'gray')+(ops()&&p.status==='Pending'&&active?'<div style="margin-top:6px">'+btn('Confirm demo funding','confirm-pledge','sm',s.id+'|'+p.id)+'</div>':'')+'</div></div>').join('')||'<p class="small muted">No pledges yet.</p>')+(active&&!s.review&&available(s)>0?'<div style="margin-top:15px">'+btn('Sponsor this delivery '+icon('heart'),'pledge','primary full',s.id)+'</div>':'')+(ops()&&active?'<h3>Operations controls</h3>'+(s.status==='Planning'?form('quote','<div class="form-grid">'+field('linehaul','Transportation ($)','number',s.linehaul,'required min="0" step="0.01"')+field('handling','Handling / stops ($)','number',s.handling,'required min="0" step="0.01"')+field('fee','BHD coordination ($)','number',s.fee,'required min="0" step="0.01"')+'</div>',s.id,'Save quote')+'<hr class="rule">'+(!s.exchangeControlled?form('capacity',select('carrier','Assign capacity',['Select capacity','Valley Community Fleet · refrigerated','Heartland Transport · ambient','Prairie Line Logistics · refrigerated'],s.carrier||'Select capacity')+'<label class="check"><input type="checkbox" name="validated" '+(s.validated?'checked':'')+'> I reviewed weight, pallet space, temperature, shelf life, stop sequence, and receiving appointments.</label>',s.id,'Save capacity review'):''):'')+(s.review?'<div class="row wrap" style="margin-top:15px">'+btn('Resolve review','resolve','',s.id)+btn('Release demo funding','release-funds','danger',s.id)+'</div>':'')+'<h3>Dispatch readiness</h3>'+[[acceptedAll,'Recipient allocations accepted'],[confirmed(s)>=target(s)&&target(s)>0,'Transportation funding confirmed'],[!!s.carrier&&s.validated,'Capacity and route reviewed'],[!s.review&&(!f||openFood(f)),'Offer available; changes resolved'],...(s.exchangeControlled?[[!!s.lot&&shipmentEvidence(s).some(d=>d.kind==='Bill of lading'),'Lot reference and BOL attached'],[partnerBy(s.carrierPartnerId)?.status==='Reviewed','Carrier onboarding reviewed'],[!s.orderFundingId||orderSum(order(s.orderFundingId),'food','Confirmed')>=orderTarget(order(s.orderFundingId),'food'),'Food purchase balance confirmed']]:[])].map(([ok,l])=>'<div class="check">'+icon(ok?'check':'clock')+'<span>'+l+'</span>'+badge(ok?'Ready':'Waiting',ok?'teal':'amber')+'</div>').join('')+(s.status==='Planning'?'<button class="btn dark full" data-action="dispatch" data-id="'+s.id+'" '+(canDispatch(s)?'':'disabled')+'>Release for pickup</button>':btn('Record delivery confirmation','deliver','primary full',s.id))+'<div style="margin-top:12px">'+btn('Cancel delivery','cancel','danger full',s.id)+'</div>':'')+(ops()&&s.status==='Canceled'&&activePledges(s).length?'<h3>Reconcile canceled delivery</h3>'+btn('Release demo funding','release-funds','danger full',s.id):'')+'<h3>Delivery timeline</h3>'+s.events.map(t=>'<div class="timeline">'+esc(t)+'</div>').join('')+(s.status==='Delivered'?'<div style="margin-top:16px">'+btn('View delivery receipt','receipt','full',s.id)+'</div>':'<div class="timeline muted">Delivery confirmation pending</div>'),s.id+' · TRANSPORTATION');}
function receiptDialog(sid){const s=ship(sid),r=s.receipt;if(!r)return;dialog('Delivery confirmed','<div class="success">'+icon('check')+'</div>'+badge('Demonstration receipt','teal')+'<h3 style="font-size:21px">'+esc(s.title)+'</h3><div class="details">'+detail('Delivery',s.id)+detail('Receipt date',date(r.date))+detail('Received by',r.name)+detail('Actual pounds',num(r.pounds))+detail('Route',s.dest)+detail('Transportation funding',money(confirmed(s)))+'</div>'+(r.pounds<s.pounds?'<div class="note amber">Quantity exception: '+num(s.pounds-r.pounds)+' lb below plan. Impact uses actual received pounds.</div>':'')+'<p>'+esc(r.note)+'</p>'+(r.photo?'<img src="'+r.photo+'" alt="Delivery evidence" style="width:100%;border-radius:8px;margin-top:15px">':'<div class="note">No photo attached. This is a fictional demonstration receipt.</div>')+'<hr class="rule">'+btn(icon('download')+' Download receipt','download-receipt','full',s.id),s.id+' · DELIVERY EVIDENCE');}
function deliveryDialog(sid){const s=ship(sid);if(!ops()||s.status!=='In transit')return;dialog('Confirm the delivery',form('deliver',field('name','Receiving contact','text','','required maxlength="80"')+field('pounds','Actual pounds received','number',s.pounds,'required min="1" max="'+s.pounds+'" step="1"')+field('date','Receipt date','date',s.date,'required min="'+s.date+'"')+field('photo','Optional delivery photo','file','','accept="image/png,image/jpeg,image/webp"')+area('notes','Receipt notes')+'<label class="check"><input type="checkbox" required> All recipient stops are complete. I reviewed quantities, condition, and delivery evidence.</label><p class="small muted" style="margin-bottom:15px">Shortfalls remain visible on the receipt. Photos stay local, maximum 1 MB.</p>',sid,'Confirm demo delivery','primary'),sid+' · PROOF OF DELIVERY',true);}
function profileDialog(){const p=state.profiles[state.bank]||{};dialog('Receiving preferences',form('profile',field('hours','Receiving hours','text',p.hours||'Mon–Fri, 8 am–3 pm','required maxlength="100"')+select('temp','Temperature capability',['Ambient','Ambient + refrigerated','Ambient + refrigerated + frozen'],p.temp||'Ambient + refrigerated')+field('pallets','Available storage (pallets)','number',p.pallets||20,'required min="1" step="1"')+area('needs','Recurring product needs',p.needs||'Fresh produce and shelf-stable protein')+'<p class="small muted" style="margin-bottom:15px">Preferences support matching; each shipment still needs receiving confirmation.</p>','','Save preferences'),esc(state.bank),true);}
function recurringDialog(){dialog('Adopt a delivery route','<p class="muted">Start with a monthly cap and a community to support. Schedule and pricing must be agreed before a live commitment.</p>'+form('recurring',field('company','Sponsor / company','text','','required maxlength="80"')+select('route','Preferred route',['Indianapolis → Dayton → Columbus','Louisville → Cincinnati','Fort Wayne → Dayton'])+field('cap','Monthly sponsorship cap ($)','number',2000,'required min="1" step="0.01"')+select('frequency','Preferred frequency',['Weekly','Twice monthly','Monthly'])+area('notes','Priorities or preferences'),'','Record demo interest','primary'),'RECURRING SPONSORSHIP',true);}
function success(title,text,action='quick',id='transport'){dialog(title,'<div class="success">'+icon('check')+'</div><p>'+text+'</p><div class="note" style="margin-bottom:20px">Saved in this browser’s demonstration data.</div>'+btn('Continue '+icon('arrow'),action,'dark full',id),'DEMO UPDATED',true);}
function download(name,text,mime='text/csv'){const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csv=rows=>rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
async function photoData(f){if(!f?.size)return null;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1048576)throw Error('Use a PNG, JPEG, or WebP photo under 1 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read photo.'));r.readAsDataURL(f);});}
document.addEventListener('click',e=>{const n=e.target.closest('[data-page],[data-action]');if(!n){if(e.target.matches('[data-backdrop]'))closeDialog();return;}if(n.dataset.page){go(n.dataset.page);return;}const a=n.dataset.action,v=n.dataset.id;switch(a){
case 'close':closeDialog();break;case 'quick':if(v==='donate'){fundingView='general';go('sponsor');}else if(v==='order'){fundingView='orders';go('sponsor');}else if(v==='sponsor'){fundingView='deliveries';go('sponsor');}else v==='offer'?postDialog():go(v);break;case 'food':foodDetail(v);break;case 'post':postDialog();break;case 'ship':shipDetail(v);break;case 'pledge':pledgeDialog(v);break;case 'match':pledgeDialog(v,true);break;case 'recurring':recurringDialog();break;case 'profile':profileDialog();break;case 'deliver':deliveryDialog(v);break;case 'receipt':receiptDialog(v);break;case 'filter':type=v;render();break;case 'transport-view':transportView=v;render();break;case 'amount':document.querySelector('[name="amount"]').value=v;break;case 'impact-records':document.getElementById('impact-records').scrollIntoView({behavior:'smooth'});break;
case 'save-search':{const s={query,type,temp};if(!state.saved.some(x=>JSON.stringify(x)===JSON.stringify(s)))state.saved.push(s);save();toast('Search saved. Matching new demo posts appear in Activity.');break;}
case 'approve':case 'decline':{if(!['donor','ops'].includes(state.role))return;const [fid,aid]=v.split('|'),f=item(fid),al=f.allocations.find(x=>x.id===aid);if(al?.status!=='Requested')return;if(a==='approve'&&!openFood(f)){toast('This offer is closed or expired.');return;}al.status=a==='approve'?'Confirmed':'Declined';notify(al.bank+': '+al.pallets+' pallets '+al.status.toLowerCase()+'.');save();render();foodDetail(fid);break;}
case 'confirm-pledge':{if(!ops())return;const [sid,pid]=v.split('|'),s=ship(sid),p=s.pledges.find(p=>p.id===pid);if(p?.status!=='Pending'||['Canceled','Delivered'].includes(s.status))return;if(confirmed(s)+p.amount>target(s)){toast('Reconcile pledges against the revised quote first.');return;}p.status='Confirmed';s.events.push(money(p.amount)+' demo funding confirmed');notify(sid+': funding confirmed from '+p.sponsor);save();render();shipDetail(sid);break;}
case 'dispatch':{if(!ops())return;const s=ship(v);if(!canDispatch(s)){toast('Complete all dispatch checks first.');return;}s.status='In transit';s.events.push('Released for pickup · demo shipment in transit');notify(s.id+': released to '+s.carrier);save();render();shipDetail(v);break;}
case 'resolve':{if(!ops())return;const s=ship(v);if(s.status==='Canceled'||confirmed(s)+pending(s)>target(s)){toast('Reconcile funding before resolving the review.');return;}if(s.itemId&&!openFood(item(s.itemId))){toast('This food is unavailable. Cancel and reconcile the delivery.');return;}dialog('Resolve the change review',form('resolve','<p>Confirm the revised terms with affected recipients and sponsors.</p><label class="check"><input type="checkbox" required> In this demo, affected parties reviewed and accepted the changes.</label>',v,'Resolve demo review'),v,true);break;}
case 'release-funds':if(ops())dialog('Reconcile the sponsorships',form('release-funds','<p>This updates demo records only. It does not return money or contact sponsors.</p><label class="check"><input type="checkbox" required> I simulated sponsor notification and release or return of active pledges for this delivery.</label>',v,'Release demo funding','danger'),v,true);break;
case 'cancel':if(ops())dialog('Cancel this delivery',form('cancel',area('reason','Reason for cancellation'),v,'Cancel demo delivery','danger'),v,true);break;
case 'close-offer':if(['donor','ops'].includes(state.role))dialog('Close this opportunity',form('close-offer','<p>Linked active deliveries will be flagged for review. Funding remains assigned until reconciled.</p>',v,'Close demo opportunity','danger'),v,true);break;
case 'create-shipment':{if(!ops()||state.shipments.some(s=>s.itemId===v))return;const f=item(v),sid='D-'+(2100+state.shipments.length);state.shipments.unshift({id:sid,itemId:v,title:f.product,origin:f.city,route:[f.city,'Recipient to confirm'],dest:'Recipient route to confirm',date:f.deadline,pallets:f.pallets,pounds:f.pounds,temp:f.temp,status:'Planning',linehaul:0,handling:0,fee:0,carrier:'',validated:false,review:'',pledges:[],events:['Transportation request created']});save();render();shipDetail(sid);break;}
case 'activity':dialog('Network activity',(state.notifications.map(t=>'<div class="comment">'+esc(t)+'</div>').join('')||'<div class="empty">No new activity yet. Post food or sponsor a delivery to get started.</div>')+'<h3>Saved searches</h3>'+(state.saved.map(s=>'<div class="comment">'+esc(s.query||'Any location')+' · '+esc(s.type)+' · '+esc(s.temp)+'</div>').join('')||'<p class="small muted">Save a search from Food & Needs.</p>'),'YOUR DEMO ACTIVITY');break;
case 'tour':dialog('Take the five-minute tour','<div class="timeline">1. Review the produce donation<small>See 20 pallets split among three food banks.</small></div><div class="timeline">2. Confirm the final allocation<small>Switch to Donors & Sponsors and approve the five-pallet request.</small></div><div class="timeline">3. Fund the transportation<small>Pledge the remaining balance. Pledges stay pending until confirmed.</small></div><div class="timeline">4. Coordinate the delivery<small>Switch to BHD Operations. Confirm funding, assign refrigerated capacity, review the route, and release.</small></div><div class="timeline">5. Confirm receipt<small>Record delivery and see actual pounds appear in Impact.</small></div><div class="note" style="margin-bottom:20px">All records are fictional. Changes remain in this browser. The role selector demonstrates views, not secure authentication. No payments, messages, or shipments are sent.</div>'+btn('Start with the produce donation '+icon('arrow'),'food','primary full','F-1042'),'FOOD → FUNDING → DELIVERY',true);break;
case 'reset':dialog('Start the demo again?','<p>This restores the original sample records and removes local demo changes, including posts, photos, and pledges.</p><div class="row wrap" style="margin-top:20px">'+btn('Keep my changes','close')+btn('Reset demo','reset-confirm','danger')+'</div>','DEMONSTRATION DATA',true);break;
case 'reset-confirm':state=seed();save();go('home');toast('Demo restored to its starting point.');break;
case 'export':download('BHD_demo_shipments.csv',csv([['DEMO DATA','ID','Title','Origin','Destination','Pickup','Pallets','Pounds','Status','Target','Confirmed','Pending'],...state.shipments.map(s=>['Illustrative',s.id,s.title,s.origin,s.dest,s.date,s.pallets,s.pounds,s.status,target(s),confirmed(s),pending(s)])]));toast('Demo shipment export downloaded.');break;
case 'export-impact':download('BHD_demo_impact.csv',csv([['DEMO DATA','ID','Destination','Receipt date','Actual pounds','Funding applied','Received by'],...state.shipments.filter(s=>s.status==='Delivered').map(s=>['Illustrative',s.id,s.dest,s.receipt.date,s.receipt.pounds,confirmed(s),s.receipt.name])]));break;
case 'download-receipt':{const s=ship(v),r=s.receipt;download(s.id+'_demo_receipt.txt','DEMONSTRATION RECEIPT — NOT A REAL DELIVERY\n\n'+s.id+': '+s.title+'\nRoute: '+s.origin+' → '+s.dest+'\nDate: '+r.date+'\nReceived by: '+r.name+'\nActual received: '+num(r.pounds)+' lb\nTransportation funding: '+money(confirmed(s))+'\nNotes: '+r.note+'\n','text/plain');break;}
}});
document.addEventListener('change',e=>{if(e.target.id==='role'){state.role=e.target.value;save();closeDialog();render();toast(roleLabel()+' demo portal');}if(e.target.id==='bank'){state.bank=e.target.value;save();render();}if(e.target.id==='temperature'){temp=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();const el=document.getElementById('search');el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog();const d=document.querySelector('[role="dialog"]');if(d&&e.key==='Tab'){const els=[...d.querySelectorAll('button:not([disabled]),input:not([type=hidden]),select,textarea,a[href]')].filter(n=>n.offsetParent!==null);if(els.length){if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action][tabindex="0"]')){e.preventDefault();e.target.click();}});
document.addEventListener('submit',async e=>{const el=e.target.closest('[data-form]');if(!el)return;e.preventDefault();const f=new FormData(el),v=el.dataset.id,kind=el.dataset.form;const str=n=>String(f.get(n)||'').trim(),required=n=>{const x=str(n);if(!x)throw Error('Complete all required fields.');return x;},number=n=>{const x=Number(f.get(n));if(!Number.isFinite(x))throw Error('Enter a valid number.');return x;};el.querySelector('.error').textContent='';const submit=el.querySelector('[type=submit]');submit.disabled=true;try{switch(kind){
case 'request':{const it=item(v),qty=number('pallets');if(state.role!=='bank'||!openFood(it))throw Error('This offer is not open to requests.');if(!Number.isInteger(qty)||qty<1||qty>it.pallets-held(it))throw Error('That quantity is no longer available.');it.allocations.push({id:uid('a'),bank:state.bank,pallets:qty,status:'Requested'});notify(state.bank+' requested '+qty+' pallets from '+it.org);save();render();foodDetail(v);toast('Request recorded. Donor approval is next.');break;}
case 'comment':{const text=required('message');if(text.length>2000)throw Error('Keep the message under 2,000 characters.');item(v).comments.push({name:state.role==='bank'?state.bank:roleLabel()+' demo',text});notify('New discussion: '+item(v).title);save();foodDetail(v);toast('Message added to the demo.');break;}
case 'post':{const pallets=number('pallets'),pounds=number('pounds'),t=str('type');if(!Number.isInteger(pallets)||pallets<1||pounds<1)throw Error('Enter a positive whole pallet count and weight.');if(str('deadline')<demoDate)throw Error('The deadline must be on or after the demo date.');const photo=await photoData(f.get('photo'));const it={id:'F-'+(1050+state.items.length),type:t,title:required('title'),product:required('product'),org:required('org'),city:required('city'),pallets,pounds,temp:str('temp'),deadline:str('deadline'),shelf:required('shelf'),price:['For sale','Shared order'].includes(t)?number('price'):0,icon:t==='Capacity'?'truck':'food',band:t==='Capacity'?'blue':t==='Food needed'?'gold':'',status:'Open',notes:str('notes'),allocations:[],comments:[],photo};state.items.unshift(it);state.saved.forEach(s=>{if((s.type==='All'||s.type===it.type)&&(s.temp==='All temperatures'||s.temp===it.temp)&&(it.title+' '+it.org+' '+it.city).toLowerCase().includes(s.query.toLowerCase()))notify('Saved search match: '+it.title);});notify('New opportunity: '+it.title);save();page='food';query='';type='All';temp='All temperatures';render();foodDetail(it.id);toast('Demo opportunity published.');break;}
case 'pledge':{const s=ship(v),amount=round(number('amount'));if(s.status!=='Planning'||s.review||amount<=0||amount>available(s))throw Error('Choose an amount within the remaining funding gap.');const sponsor=required('sponsor'),pid=uid('p');let match=0;if(str('match')==='yes'){const used=activePledges(s).filter(p=>p.kind==='Match').reduce((a,p)=>a+p.amount,0);match=round(Math.max(0,Math.min(amount,500-used,available(s)-amount)));}s.pledges.push({id:pid,sponsor,amount,status:'Pending',kind:'Direct'});if(match)s.pledges.push({id:uid('p'),sponsor:state.match.sponsor,amount:match,status:'Pending',kind:'Match',linked:pid});s.events.push(money(amount)+' transportation pledge recorded');notify(s.id+': '+money(amount)+' pledged by '+sponsor);save();render();success('Your pledge has a destination.',money(amount)+' from '+esc(sponsor)+' is reserved for '+s.id+'.'+(match?' A matching pledge of '+money(match)+' was also recorded.':'')+' Food acceptance and confirmed funding are still required before dispatch. No money was collected.','ship',v);break;}
case 'quote':{if(!ops())break;const s=ship(v);if(s.status!=='Planning')throw Error('A shipment in transit cannot be requoted.');const linehaul=round(number('linehaul')),handling=round(number('handling')),fee=round(number('fee'));if(Math.min(linehaul,handling,fee)<0||linehaul+handling+fee<=0)throw Error('Enter a positive total quote.');const changed=s.linehaul!==linehaul||s.handling!==handling||s.fee!==fee;if(changed){Object.assign(s,{linehaul,handling,fee,validated:false});if(confirmed(s)+pending(s)>0)s.review='The quote changed. Confirm revised terms with sponsors and recipients.';s.events.push('Transportation quote revised');notify(s.id+': quote revised; participant review needed.');}save();render();shipDetail(v);toast(changed?'Quote updated. Review the revised terms.':'Quote unchanged.');break;}
case 'capacity':{if(!ops())break;const s=ship(v),carrier=str('carrier');if(s.status!=='Planning')throw Error('Capacity changes require a planning shipment.');if(carrier==='Select capacity')throw Error('Choose a fleet or carrier.');if(s.temp==='Refrigerated'&&!carrier.includes('refrigerated'))throw Error('This delivery requires refrigerated capacity.');if(s.temp==='Frozen')throw Error('No frozen-capable capacity is configured in this demo.');s.carrier=carrier;s.validated=f.get('validated')==='on';s.events.push('Capacity assigned'+(s.validated?' and route reviewed':''));save();render();shipDetail(v);toast('Capacity review saved.');break;}
case 'deliver':{if(!ops())break;const s=ship(v);if(s.status!=='In transit')throw Error('Release the shipment before recording delivery.');const pounds=number('pounds');if(pounds<=0||pounds>s.pounds)throw Error('Received pounds must be within planned weight.');const photo=await photoData(f.get('photo'));s.receipt={name:required('name'),bank:s.itemId?item(s.itemId).allocations.filter(a=>a.status==='Confirmed').map(a=>a.bank).join(' / '):s.dest,pounds,date:str('date'),note:str('notes'),photo};s.status='Delivered';s.events.push('Delivery confirmed · '+num(pounds)+' lb received');notify(s.id+': delivery complete, '+num(pounds)+' lb added to impact.');save();render();receiptDialog(v);break;}
case 'profile':state.profiles[state.bank]={hours:required('hours'),temp:str('temp'),pallets:number('pallets'),needs:str('needs')};save();closeDialog();toast('Receiving preferences saved.');break;
case 'recurring':{const cap=round(number('cap'));if(cap<=0)throw Error('Enter a positive monthly cap.');state.recurring.push({company:required('company'),route:str('route'),cap,frequency:str('frequency'),notes:str('notes'),status:'Interest recorded'});notify(str('company')+': recurring sponsorship interest recorded.');save();render();success('A regular route to doing good.','Your interest in '+esc(str('route'))+', with a monthly cap of '+money(cap)+', is recorded in the demo. Schedule, price, and funding are still to be agreed.','quick','sponsor');break;}
case 'resolve':{if(!ops())break;const s=ship(v);if(s.status==='Canceled'||confirmed(s)+pending(s)>target(s))throw Error('Reconcile funding before resolving.');s.review='';s.events.push('Affected parties accepted revised terms · demo');save();render();shipDetail(v);break;}
case 'release-funds':{if(!ops())break;const s=ship(v);releaseShipmentFunding(s);s.events.push('Sponsor notification and funding release simulated');notify(s.id+': funding released in the demo.');save();render();shipDetail(v);break;}
case 'cancel':{if(!ops())break;const s=ship(v);s.review=required('reason');s.status='Canceled';s.events.push('Delivery canceled · sponsor reconciliation required');notify(s.id+': canceled. Reconcile sponsor commitments.');save();render();shipDetail(v);break;}
case 'close-offer':{if(!['donor','ops'].includes(state.role))break;item(v).status='Closed';state.shipments.filter(s=>s.itemId===v&&!['Canceled','Delivered'].includes(s.status)).forEach(s=>s.review='The food offer was marked unavailable.');notify(item(v).title+': closed; linked active deliveries flagged.');save();render();foodDetail(v);break;}
}}catch(err){if(document.body.contains(el)){el.querySelector('.error').textContent=err.message;el.querySelector('.error').scrollIntoView({block:'nearest'});}else toast(err.message);}finally{if(document.body.contains(submit))submit.disabled=false;}});
